LOCAL SOURCE EXCERPT, read from filesystem; line numbers preserved.
1: /* ASO patient chat · AG-UI-shaped event stream (simulated).
2:    A run is a list of { at, ev } where `at` is a millisecond offset and `ev`
3:    uses AG-UI event names: RUN_STARTED, STEP_STARTED / STEP_FINISHED,
4:    TOOL_CALL_START / ARGS / END / RESULT, TEXT_MESSAGE_START / CONTENT / END,
5:    STATE_DELTA (JSON Patch), CUSTOM and RUN_FINISHED. An interrupt is a
6:    RUN_FINISHED with outcome "interrupt": the agent pauses and the host
7:    decides what to draw. Playback is timestamp-based, not tick-counted, so a
8:    backgrounded tab catches up instead of drifting. Pure: no DOM here. */
9: (function (g) {
10:   'use strict';
11:   var ASO = g.ASO = g.ASO || {};
12: 
13:   function builder(threadId) {
14:     var runId = ASO.uid('run');
15:     var t = 0;
16:     var evs = [];
17: 
18:     function push(ev, dt) {
19:       t += dt || 0;
20:       evs.push({ at: t, ev: ev });
21:     }
22: 
23:     push({ type: 'RUN_STARTED', threadId: threadId, runId: runId });
24: 
25:     var api = {
26:       /* tools: [{ name, args, result, ms }] */
27:       step: function (name, tools) {
28:         push({ type: 'STEP_STARTED', stepName: name }, 160);
29:         (tools || []).forEach(function (tc) {
30:           var id = ASO.uid('tc');
31:           push({ type: 'TOOL_CALL_START', toolCallId: id, toolCallName: tc.name }, 120);
32:           push({ type: 'TOOL_CALL_ARGS', toolCallId: id, delta: JSON.stringify(tc.args || {}) }, 60);
33:           push({ type: 'TOOL_CALL_END', toolCallId: id }, 20);
34:           push({ type: 'TOOL_CALL_RESULT', toolCallId: id, content: tc.result }, tc.ms || 560);
35:         });
36:         push({ type: 'STEP_FINISHED', stepName: name }, 80);
37:         return api;
38:       },
39:       text: function (str) {
40:         var id = ASO.uid('msg');
41:         push({ type: 'TEXT_MESSAGE_START', messageId: id, role: 'assistant' }, 220);
42:         (str.match(/\S+\s*/g) || []).forEach(function (chunk) {
43:           push({ type: 'TEXT_MESSAGE_CONTENT', messageId: id, delta: chunk }, 28);
44:         });
45:         push({ type: 'TEXT_MESSAGE_END', messageId: id }, 20);
46:         return api;
47:       },
48:       /* A2UI messages travel as one CUSTOM event */
49:       surface: function (messages) {
50:         push({ type: 'CUSTOM', name: 'a2ui', value: messages }, 260);
51:         return api;
52:       },
53:       custom: function (name, value) {
54:         push({ type: 'CUSTOM', name: name, value: value }, 200);
55:         return api;
56:       },
57:       /* shared state changes as JSON Patch operations */
58:       state: function (ops) {
59:         push({ type: 'STATE_DELTA', delta: ops }, 240);
60:         return api;
61:       },
62:       finish: function () {
63:         push({ type: 'RUN_FINISHED', threadId: threadId, runId: runId, outcome: 'success' }, 140);
64:         return evs;
65:       },
66:       interrupt: function (payload) {
67:         push({ type: 'RUN_FINISHED', threadId: threadId, runId: runId, outcome: 'interrupt', interrupt: payload }, 140);
